    question: "ข้าราชการที่ต้องพ้นจากราชการเพราะการยุบส่วนราชการ หากรัฐวิสาหกิจประสงค์จะรับโอน จะถือว่า ข้าราชการผู้นั้นได้พ้นจากราชการหรือไม่",
    options: ["ก. ถือว่าพ้นจากราชการแล้ว แต่ให้บรรจุใหม่ได้", "ข. มิให้ถือว่าได้พ้นจากราชการ หากการรับโอนเสร็จสิ้นภายใน 30 วัน", "ค. ถือว่าพ้นจากราชการ แต่ได้รับสิทธิประโยชน์ต่อเนื่อง", "ง. ขึ้นอยู่กับความสมัครใจของข้าราชการผู้นั้น"],
