    question: "การที่นายกรัฐมนตรีจะมอบหมายให้รองนายกรัฐมนตรีกำกับการบริหารราชการของหลายกระทรวง สามารถทำได้หรือไม ่",
    options: ["ก. ไม่ได้ ต้องกำกับเพียงกระทรวงเดียว", "ข. ได้ โดยไม่จำกัดจำนวน", "ค. ได้ แต่ไม่เกิน 3 กระทรวง", "ง. ได้ แต่ต้องเป็นกระทรวงที่มีภารกิจเกี่ยวเนื่องกันเท่านั้น"],
