    question: "การที่นายกรัฐมนตรีจะแต่งตั้งข้าราชการจากกระทรวงเกษตรและสหกรณ์ ไปดำรงตำแหน่งในกระทรวง พาณิชย์ หากเป็นการแต่งตั้งในตำแหน่งรองอธิบดี ต้องได้รับอนุมัติจากใคร",
    options: ["ก. นายกรัฐมนตรีสั่งการได้โดยตรง", "ข. ต้องได้รับอนุมัติจากรัฐมนตรีทั้งสองกระทรวง", "ค. ต้องได้รับอนุมัติจากปลัดกระทรวงทั้งสอง", "ง. ไม่ต้องได้รับอนุมัติจากคณะรัฐมนตรี"],
