    question: "ปลัดสำนักนายกรัฐมนตรีมีอำนาจหน้าที่ควบคุมราชการประจำในสำนักนายกรัฐมนตรี ยกเว้นข้าราชการ ของส่วนราชการที่มีลักษณะใด",
    options: ["ก. ส่วนราชการที่มีฐานะเป็นกรม", "ข. ส่วนราชการที่ตั้งขึ้นใหม่", "ค. ส่วนราชการซึ่งหัวหน้าส่วนราชการขึ้นตรงต่อนายกรัฐมนตรี", "ง. ส่วนราชการที่ปฏิบัติภารกิจด้านความมั่นคง"],
