    options: ["ก. ไม่ได้ อำนาจต้องโอนไปทั้งหมด", "ข. ได้ โดยสามารถกำหนดเป็นอย่างอื่นไว้ในกฎกระทรวง", "ค. ได้ แต่ต้องเป็นเรื่องที่เกี่ยวกับงบประมาณเท่านั้น", "ง. ไม่ได้ เพราะจะทำให้สายการบังคับบัญชาสับสน"],
