    question: "การที่หัวหน้ากลุ่มภารกิจจะกำหนดให้กรม ก. ทำหน้าที่ด้านการเงินให้แก่กรม ข. ซึ่งอยู่ในกลุ่มภารกิจ เดียวกัน สามารถทำได้หรือไม่",
    options: ["ก. ไม่ได้ เพราะเป็นอำนาจของปลัดกระทรวง", "ข. ได้ โดยเป็นอำนาจของหัวหน้ากลุ่มภารกิจ", "ค. ได้ แต่ต้องได้รับความเห็นชอบจากอธิบดีทั้งสองกรมก่อน", "ง. ไม่ได้ ขัดต่อกฎหมายว่าด้วยวิธีการงบประมาณ"],
