    options: ["ก. เป็นผู้ใต้บังคับบัญชา", "ข. ปฏิบัติราชการภายใต้การกำกับดูแล", "ค. มีสถานะเท่าเทียมกัน", "ง. เป็นที่ปรึกษา"],
