    question: "ในกรณีที่ไม่มีผู้ดำรงตำแหน่งผู้อำนวยการกอง และอธิบดีไม่ได้แต่งตั้งผู้รักษาราชการแทน ใครจะเป็น ผู้รักษาราชการแทน",
