    explanation: "กฎหมายกำหนดลำดับการรักษาราชการแทนถึงระดับหัวหน้ากอง (ตาม ม. 47) แต่ไม่ได้ กำหนดลำดับอัตโนมัติในระดับต่ำกว่านั้น"
