    question: "หากรัฐมนตรีว่าการกระทรวงมหาดไทยมอบอำนาจในการอนุญาตเรื่องหนึ่งให้ผู้ว่าราชการจังหวัด กรุงเทพมหานคร ผู้ว่าฯ กทม. สามารถมอบอำนาจนั้นต่อไปให้ปลัด กทม. ได้หรือไม่",
