    options: ["ก. ไม่ถูกต้อง ต้องแต่งตั้งจากข้าราชการในกรม ข. เท่านั้น", "ข. ถูกต้อง เป็นอำนาจของปลัดกระทรวง", "ค. ไม่ถูกต้อง เพราะเป็นอำนาจของรัฐมนตรี", "ง. ถูกต้อง แต่ต้องได้รับความเห็นชอบจากคณะรัฐมนตรี"],
