    question: "การมอบอำนาจของหัวหน้าคณะผู้แทนให้บุคคลอื่นในคณะผู้แทนปฏิบัติราชการแทน จะต้องเป็นไป ตามที่ใดกำหนด",
    options: ["ก. ตามที่หัวหน้าคณะผู้แทนเห็นสมควร", "ข. ตามระเบียบที่คณะรัฐมนตรีกำหนด", "ค. ตามที่ปลัดกระทรวงการต่างประเทศกำหนด", "ง. ตามที่เอกอัครราชทูตกำหนด"],
