    question: "การจัดตั้งงบประมาณของจังหวัดหรือกลุ่มจังหวัด ต้องเป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่ กำหนดในกฎหมายใด",
    options: ["ก. พระราชบัญญัติวิธีการงบประมาณ", "ข. พระราชกฤษฎีกา", "ค. กฎกระทรวงมหาดไทย", "ง. ระเบียบสำนักนายกรัฐมนตรี"],
