    question: "ในกรณีที่ไม่มีผู้ดำรงตำแหน่งอธิบดี และไม่มีรองอธิบดี ปลัดกระทรวงสามารถแต่งตั้งข้าราชการพลเรือน จากกระทรวงอื่นมารักษาราชการแทนได้หรือไม่",
    options: ["ก. ได้ หากมีความรู้ความสามารถเหมาะสม", "ข. ไม่ได้ ต้องเป็นข้าราชการในกรมนั้นเท่านั้น", "ค. ได้ แต่ต้องได้รับความเห็นชอบจากรัฐมนตรี", "ง. ไม่ได้ เว้นแต่นายกรัฐมนตรีจะมีคำสั่งเป็นพิเศษ"],
