    options: ["ก. พระราชบัญญัตินี้", "ข. กฎหมายว่าด้วยการจัดตั้งองค์กรปกครองส่วนท้องถิ่นแต่ละรูปแบบ", "ค. รัฐธรรมนูญ", "ง. คำสั่งกระทรวงมหาดไทย"],
