    question: "เลขาธิการ ก.พ.ร. รับผิดชอบการปฏิบัติราชการขึ้นตรงต่อใคร",
    options: ["ก. ประธาน ก.พ.ร.", "ข. คณะรัฐมนตรี", "ค. ปลัดสำนักนายกรัฐมนตรี", "ง. นายกรัฐมนตรี"],
