    options: ["ก. เพื่อให้การทำงานเป็นไปในทิศทางเดียวกันตามนโยบาย", "ข. เพื่อลดความขัดแย้งระหว่างกรม", "ค. เพื่อให้การใช้ทรัพยากรมีประสิทธิภาพ", "ง. ถูกทุกข้อ"],
