    options: ["ก. ได้ เป็นอำนาจของอธิบดี", "ข. ไม่ได้ ต้องให้ปลัดกระทรวงเป็นผู้แต่งตั้ง", "ค. ได้ แต่ต้องเป็นหัวหน้ากองที่มีอาวุโสสูงสุดเท่านั้น", "ง. ไม่ได้ เพราะอำนาจแต่งตั้งเป็นของผู้บังคับบัญชาเหนือขึ้นไป"],
