    question: "การที่รัฐมนตรีช่วยว่าการกระทรวงจะปฏิบัติราชการแทนรัฐมนตรีว่าการกระทรวงในกรณีที่ รัฐมนตรีว่าการฯ ไม่อยู่ ถือเป็นการกระทำประเภทใด",
    options: ["ก. การปฏิบัติราชการแทน", "ข. การรักษาราชการแทน", "ค. การได้รับมอบหมาย", "ง. การสั่งการโดยชอบ"],
    answer: "ข",
