    question: "หากนายอำเภอไกล่เกลี่ยข้อพิพาททางอาญาเรื่องทำร้ายร่างกายจนเป็นเหตุให้เกิดอันตรายแก่กายหรือ จิตใจ ซึ่งเป็นความผิดอันยอมความได้ และคู่กรณีตกลงกันได้ คดีอาญาจะมีผลอย่างไร",
    options: ["ก. อัยการสั่งไม่ฟ้อง", "ข. ศาลรอการลงโทษ", "ค. คดีอาญาเป็นอันเลิกกัน", "ง. ผู้กระทำผิดยังคงมีประวัติอาชญากรรม"],
