    question: "การไกล่เกลี่ยข้อพิพาททางแพ่งในระดับอำเภอมีผลดีอย่างไรต่อระบบศาล",
    options: ["ก. ช่วยลดปริมาณคดีขึ้นสู่ศาล", "ข. ทำให้คดีในศาลพิจารณาได้เร็วขึ้น", "ค. ช่วยแบ่งเบาภาระของผู้พิพากษา", "ง. ถูกทุกข้อ"],
