    question: "หากกรรมการผู้ทรงคุณวุฒิใน ก.พ.ร. ถูกไล่ออกจากรัฐวิสาหกิจเพราะทุจริตต่อหน้าที่ จะขาดคุณสมบัติ หรือไม ่",
    options: ["ก. ไม่ขาด เพราะไม่ใช่การไล่ออกจากราชการ", "ข. ขาดคุณสมบัติ", "ค. ไม่ขาด หากเหตุเกิดก่อนเข้ารับตำแหน่ง", "ง. ขึ้นอยู่กับว่าความผิดนั้นถึงที่สุดแล้วหรือไม่"],
