    question: "อำนาจของ ก.พ.ร. ในการ \"ตีความและวินิจฉัยปัญหา\" ครอบคลุมถึงกฎหมายใดบ้าง",
    options: ["ก. พระราชบัญญัตินี้เท่านั้น", "ข. พระราชบัญญัตินี้ และกฎหมายว่าด้วยการปรับปรุงกระทรวง ทบวง กรม", "ค. กฎหมายเกี่ยวกับการบริหารราชการแผ่นดินทุกฉบับ", "ง. กฎหมายที่คณะรัฐมนตรีมอบหมาย"],
