    question: "การจัดระเบียบราชการในทบวงซึ่งสังกัดสำนักนายกรัฐมนตรี จะต้องมี \"สำนักงานรัฐมนตรี\" หรือไม่",
    options: ["ก. ต้องมีเสมอ", "ข. ไม่ต้องม ี", "ค. มีหรือไม่ก็ได้", "ง. มี ตามที่กฎหมายกำหนด"],
