    options: ["ก. ได้ หากมีอาวุโสสูงสุด", "ข. ไม่ได้ ต้องเป็นระดับอธิบดีหรือเทียบเท่า", "ค. ได้ แต่ต้องได้รับความเห็นชอบจาก ครม.", "ง. ไม่ได้ เว้นแต่ปลัดกระทรวงจะสั่งการไว้ก่อน"],
