    options: ["ก. ได้ เป็นผู้บังคับบัญชาโดยตรง", "ข. ไม่ได้ เป็นอำนาจของกระทรวงมหาดไทย", "ค. ได้ แต่ต้องได้รับความเห็นชอบจากคณะกรมการจังหวัด", "ง. ได้ หากได้รับมอบหมายจากปลัดกระทรวงหรืออธิบดี"],
