    options: ["ก. การทำงานให้เสร็จตามเป้าหมายที่วางไว้", "ข. การทำงานโดยใช้งบประมาณน้อยที่สุด", "ค. การทำงานที่ประชาชนพึงพอใจ", "ง. การทำงานตามคำสั่งผู้บังคับบัญชา"],
