    question: "การที่นายกรัฐมนตรีจะแต่งตั้งผู้ทรงคุณวุฒิเป็น \"ประธานที่ปรึกษา\" สามารถทำได้หรือไม่",
    options: ["ก. ไม่ได้ ต้องเป็นแค่ \"ที่ปรึกษา\"", "ข. ได้", "ค. ไม่ได้ เพราะต้องมีนายกฯ เป็นประธาน", "ง. ได้ แต่ต้องมาจากข้าราชการบำนาญเท่านั้น"],
