    question: "การจัดระเบียบราชการใน \"ทบวง\" ซึ่งสังกัดกระทรวง จะต้องมี \"กรม\" อยู่ในสังกัดเสมอไปหรือไม่",
    options: ["ก. ต้องมีเสมอ", "ข. ไม่จำเป็น อาจไม่มีกรมก็ได้", "ค. ต้องมีอย่างน้อย 1 กรม", "ง. ขึ้นอยู่กับขนาดของทบวง"],
