    options: ["ก. ขาดคุณสมบัติ เพราะต้องโทษจำคุก", "ข. ไม่ขาดคุณสมบัติ เพราะเป็นความผิดที่ได้กระทำโดยประมาท", "ค. ขาดคุณสมบัติ เพราะเป็นเหตุให้ผู้อื่นถึงแก่ความตาย", "ง. ไม่ขาดคุณสมบัติ หากศาลให้รอการลงโทษ"],
