    question: "การแบ่งส่วนราชการภายในสำนักงานตำรวจแห่งชาติให้ตราเป็นกฎหมายใด",
    options: ["ก. พระราชบัญญัติ", "ข. พระราชกฤษฎีกา", "ค. กฎกระทรวง", "ง. ประกาศสำนักงานตำรวจแห่งชาติ"],
