    question: "ข้อใดคือความแตกต่างที่สำคัญระหว่าง \"ทบวงซึ่งมีฐานะเทียบเท่ากระทรวง\" กับ \"ทบวงซึ่งสังกัด กระทรวง\"",
    options: ["ก. รัฐมนตรีว่าการทบวงเทียบเท่ากระทรวงเป็นสมาชิกคณะรัฐมนตรีโดยตรง", "ข. ทบวงเทียบเท่ากระทรวงมีโครงสร้างและเอกภาพในการบริหารมากกว่า", "ค. งบประมาณของทบวงสังกัดกระทรวงอาจต้องผ่านความเห็นชอบของกระทรวงแม่", "ง. ถูกทุกข้อ"],
