    id: 550,
    question: "การที่นายอำเภอมีหน้าที่รักษาการให้เป็นไปตามกฎหมาย ในกรณีที่กฎหมายมิได้บัญญัติว่าเป็นหน้าที่ของ ผู้ใดโดยเฉพาะ มีความสำคัญอย่างไร",
    options: ["ก. ทำให้นายอำเภอเป็นผู้บังคับใช้กฎหมายทุกฉบับในพื้นที่", "ข. ป้องกันไม่ให้เกิดช่องว่างในการบังคับใช้กฎหมายในระดับอำเภอ", "ค. เพิ่มอำนาจให้นายอำเภอเหนือกว่าส่วนราชการอื่น", "ง. ทำให้การบริหารราชการในอำเภอเป็นไปอย่างรวดเร็ว"],
