    question: "หาก ก.ธ.จ. พบว่ามีการทุจริตในหน่วยงานของรัฐในจังหวัด และได้แจ้งให้ผู้ว่าฯ ดำเนินการแล้ว แต่ผู้ว่าฯ เพิกเฉย ก.ธ.จ. ควรทำอย่างไรต่อไป",
    options: ["ก. ไม่มีอำนาจทำอะไรได้อีก", "ข. ยื่นเรื่องต่อ ป.ป.ช. หรือหน่วยงานตรวจสอบอื่น", "ค. รายงานต่อนายกรัฐมนตรีโดยตรง", "ง. เปิดเผยข้อมูลต่อสาธารณะ"],
