    options: ["ก. รายรับ กับ รายจ่าย", "ข. ผลลัพธ์ที่ได้ กับ ทรัพยากรที่ใช้ไป", "ค. ความพึงพอใจของประชาชน กับ งบประมาณที่ใช้", "ง. จำนวนงานที่เสร็จ กับ เวลาที่ใช้"],
