    options: ["ก. สิ้นสุดลง", "ข. ไม่สิ้นสุด โอนไปยังรองอธิบดีคนใหม่", "ค. ไม่สิ้นสุด อำนาจกลับคืนสู่อธิบดี", "ง. สิ้นสุดลงเฉพาะส่วนที่ยังไม่ได้ดำเนินการ"],
