    options: ["ก. เพื่อจัดตั้งสำนักงานคณะกรรมการกฤษฎีกา", "ข. เพื่อรองรับการจัดตั้งสำนักงานคณะกรรมการจัดระบบการจราจรทางบก", "ค. เพื่อเพิ่มอำนาจให้นายกรัฐมนตรี", "ง. เพื่อแก้ไขเรื่องการมอบอำนาจ"],
