    question: "ในกรณีที่นายกรัฐมนตรีเป็นผู้บังคับบัญชาส่วนราชการที่มีฐานะเป็นกรมโดยตรง การมอบหมายให้รอง นายกฯ ปฏิบัติราชการแทนนั้น มีผลเท่ากับการโอนอำนาจบังคับบัญชาหรือไม่",
    options: ["ก. ใช่ เป็นการโอนอำนาจเด็ดขาด", "ข. ไม่ใช่ เป็นการปฏิบัติราชการแทน", "ค. ใช่ แต่เฉพาะเรื่องที่ระบุไว้", "ง. ไม่ใช่ เป็นเพียงการกำกับดูแล"],
