    question: "หากนายกรัฐมนตรีเห็นว่ามติของคณะรัฐมนตรีฉบับหนึ่งไม่ถูกต้อง จะสามารถสั่งยับยั้งได้หรือไม่",
    options: ["ก. ได้ ในฐานะหัวหน้ารัฐบาล", "ข. ไม่ได้ เพราะตนเองก็เป็นส่วนหนึ่งของมตินั้น", "ค. ได้ แต่ต้องนำเข้า ครม. เพื่อทบทวน", "ง. ไม่ได้ เป็นอำนาจของรัฐสภา"],
