    question: "หากรัฐมนตรีว่าการกระทรวงมอบหมายอำนาจในการอนุมัติโครงการให้ปลัดกระทรวง แต่ต่อมารัฐมนตรี เห็นว่าโครงการหนึ่งไม่เหมาะสม จะสามารถยกเลิกการอนุมัติของปลัดกระทรวงได้หรือไม่",
    options: ["ก. ไม่ได้ เพราะมอบอำนาจไปแล้ว", "ข. ได้ เพราะผู้มอบอำนาจยังคงมีอำนาจและหน้าที่กำกับดูแล", "ค. ไม่ได้ เว้นแต่ปลัดกระทรวงจะยินยอม", "ง. ได้ แต่ต้องชดใช้ค่าเสียหายที่เกิดขึ้น"],
