    question: "หากไม่มีผู้ดำรงตำแหน่งอธิบดี และรองอธิบดีที่มีอยู่ไม่ยอมรักษาราชการแทน ปลัดกระทรวงจะ ดำเนินการอย่างไร",
    options: ["ก. บังคับให้รองอธิบดีรักษาราชการแทน", "ข. แต่งตั้งข้าราชการคนอื่นในกรมเป็นผู้รักษาราชการแทน", "ค. เสนอรัฐมนตรีให้ย้ายรองอธิบดี", "ง. ถูกทุกข้อ"],
