    question: "หากจังหวัด ก. และจังหวัด ข. ต้องการจัดทำแผนพัฒนาร่วมกันในลักษณะกลุ่มจังหวัด จะต้องดำเนินการ อย่างไร",
    options: ["ก. ให้ผู้ว่าฯ ทั้งสองตกลงกันเอง", "ข. เสนอให้กระทรวงมหาดไทยประกาศเป็นกลุ่มจังหวัด", "ค. ให้นำความในเรื่องการจัดทำแผนพัฒนาจังหวัดมาใช้บังคับโดยอนุโลม", "ง. ไม่สามารถทำได้"],
