    options: ["ก. ต้องดำเนินการให้แล้วเสร็จภายใน 30 วัน", "ข. ต้องตั้งกรรมการสอบสวนวินัยทันที", "ค. ให้ดำเนินการตามขั้นตอนของกฎหมายที่เกี่ยวข้อง", "ง. ต้องรายงานผลให้ ก.ธ.จ. ทราบทุกระยะ"],
