    options: ["ก. พ้นจากตำแหน่งกรรมการ ก.พ.ร.", "ข. สามารถเป็นควบคู่กันได้", "ค. ต้องเลือตำแหน่งใดตำแหน่งหนึ่งภายใน 7 วัน", "ง. พักการปฏิบัติหน้าที่กรรมการ ก.พ.ร. ไว้ก่อน"],
