    question: "หากไม่มีผู้ดำรงตำแหน่งรัฐมนตรีว่าการทบวง และไม่มีรัฐมนตรีช่วยฯ ใครจะเป็นผู้รักษาราชการแทน",
    options: ["ก. ปลัดทบวง", "ข. คณะรัฐมนตรีมอบหมายให้รัฐมนตรีคนใดคนหนึ่ง", "ค. อธิบดีในทบวงที่มีอาวุโสสูงสุด", "ง. นายกรัฐมนตรี (ถ้าทบวงสังกัดสำนักนายกฯ) หรือ รมว.กระทรวง (ถ้าทบวงสังกัดกระทรวง)"],
