    options: ["ก. ไม่ได้ การมอบอำนาจต่อทำได้เฉพาะกรณีที่ผู้ว่าฯ ได้รับมอบอำนาจมาอีกทอดหนึ่ง", "ข. ได้ หากผู้ว่าฯ กำหนดหลักเกณฑ์ให้ทำได้", "ค. ไม่ได้โดยเด็ดขาด", "ง. ได้ หากนายอำเภอเป็นผู้ใต้บังคับบัญชาโดยตรง"],
