    question: "หากมี \"ผู้ช่วยอธิบดี\" กฎหมายจะถือว่ามีลำดับการรักษาราชการแทนอย่างไร",
    options: ["ก. ก่อนรองอธิบดี", "ข. หลังรองอธิบดี", "ค. เทียบเท่ารองอธิบดี", "ง. กฎหมายไม่ได้กำหนดตำแหน่งผู้ช่วยอธิบดีไว้ในลำดับการรักษาราชการแทน"],
