    question: "หากผู้ว่าราชการจังหวัดมีหลายคน (เช่น ใน กทม.) ใครจะเป็นประธานคณะกรมการจังหวัด",
    options: ["ก. ผู้ว่าฯ ที่มีอาวุโสสูงสุด", "ข. ปลัด กทม.", "ค. กฎหมายนี้ไม่ใช้บังคับกับ กทม. ในเรื่องคณะกรมการจังหวัด", "ง. ให้ผู้ว่าฯ สลับกันเป็นประธาน"],
