    options: ["ก. ไม่ทับซ้อน ก.พ.ร. ดูภาพรวมเชิงระบบ ส่วน ก.พ. ดูการบริหารรายบุคคล", "ข. ทับซ้อนกันโดยสิ้นเชิง", "ค. ทับซ้อนกันบางส่วน", "ง. ก.พ.ร. มีอำนาจเหนือกว่า ก.พ."],
