    question: "การที่นายกรัฐมนตรีมีอำนาจสั่งให้ข้าราชการไปปฏิบัติราชการที่สำนักนายกรัฐมนตรีนั้น เป็นการ \"ยืมตัว\" หรือ \"โอนย้าย\"",
    options: ["ก. เป็นการยืมตัวชั่วคราว", "ข. เป็นการโอนย้ายถาวร", "ค. เป็นได้ทั้งสองอย่าง ขึ้นอยู่กับคำสั่ง", "ง. เป็นการปฏิบัติราชการแทนนายกรัฐมนตรี"],
