    question: "หากรัฐมนตรีว่าการกระทรวงไม่อยู่ และได้มอบหมายงานให้รัฐมนตรีช่วยว่าการกระทรวงปฏิบัติราชการ แทน ถือเป็นการกระทำประเภทใด",
    options: ["ก. การมอบอำนาจ", "ข. การรักษาราชการแทน", "ค. การปฏิบัติราชการแทน", "ง. เป็นทั้งการมอบอำนาจและปฏิบัติราชการแทน"],
