    question: "หากไม่มีผู้ดำรงตำแหน่งรัฐมนตรีว่าการกระทรวง และรัฐมนตรีช่วยว่าการกระทรวงก็ไม่อาจปฏิบัติ ราชการได้ คณะรัฐมนตรีจะมอบหมายให้ \"รัฐมนตรีว่าการกระทรวงอื่น\" มารักษาราชการแทนได้หรือไม่",
    options: ["ก. ได ้", "ข. ไม่ได้ ต้องเป็นรัฐมนตรีช่วยว่าการกระทรวงอื่น", "ค. ไม่ได้ ต้องเป็นปลัดกระทรวงนั้น", "ง. ไม่ได้ ต้องให้นายกรัฐมนตรีรักษาการแทน"],
