    options: ["ก. ได้ เป็นดุลพินิจของปลัดกระทรวง", "ข. ไม่ได้ ต้องเป็นข้าราชการในกรมนั้นเท่านั้น", "ค. ได้ แต่ต้องได้รับความเห็นชอบจากรัฐมนตรี", "ง. ได้ หากนายกรัฐมนตรีเห็นชอบ"],
