    question: "การประชุมเพื่อจัดทำแผนพัฒนาจังหวัด ใครมีหน้าที่จัดให้มีการประชุม",
    options: ["ก. หัวหน้าสำนักงานจังหวัด", "ข. ปลัดจังหวัด", "ค. ผู้ว่าราชการจังหวัด", "ง. ประธานคณะกรรมการธรรมาภิบาลจังหวัด"],
    answer: "ค",
