    question: "หากคู่กรณีในคดีมรดกที่มีทุนทรัพย์ 1 ล้านบาท ตกลงยินยอมให้ใช้วิธีไกล่เกลี่ยที่อำเภอ จะสามารถทำได้ หรือไม ่",
    options: ["ก. ไม่ได้ เพราะทุนทรัพย์เกินสองแสนบาท", "ข. ได้ หากมีการกำหนดในพระราชกฤษฎีกา", "ค. ได้ เพราะเป็นคดีเกี่ยวกับมรดก", "ง. ไม่ได้ เพราะคดีมรดกมีความซับซ้อน"],
