    question: "การที่ ก.พ.ร. มีอำนาจเสนอแนะต่อ ครม. เกี่ยวกับ \"ค่าตอบแทน\" ในระบบราชการ มีเป้าหมายเพื่อให้ เกิดผลอย่างไร",
    options: ["ก. เพื่อให้ข้าราชการมีรายได้สูงขึ้น", "ข. เพื่อให้ค่าตอบแทนสอดคล้องกับผลงานและประสิทธิภาพ", "ค. เพื่อลดความเหลื่อมล้ำของค่าตอบแทน", "ง. เพื่อให้การเบิกจ่ายงบประมาณง่ายขึ้น"],
