    question: "\"หน่วยบริการรูปแบบพิเศษ\" สามารถให้บริการแก่ส่วนราชการอื่นได้หรือไม่",
    options: ["ก. ไม่ได้ ต้องให้บริการแก่ส่วนราชการที่กำกับดูแลเท่านั้น", "ข. ได้", "ค. ได้ แต่ต้องคิดค่าบริการในอัตราที่ ครม. กำหนด", "ง. ไม่ได้ เพราะจะเกิดการทำงานซ้ำซ้อน"],
