    options: ["ก. ให้ถือว่าผ่านการอนุมัติ", "ข. ให้ถือว่าไม่ผ่านการอนุมัติ", "ค. ให้ประธานร่วมเป็นผู้ชี้ขาด", "ง. ให้นำเรื่องเสนอ ครม. เพื่อวินิจฉัย"],
