    question: "\"ทบวง\" ซึ่งสังกัดกระทรวง มีรัฐมนตรีว่าการทบวงเป็นผู้บังคับบัญชา แต่ต้องปฏิบัติราชการภายใต้การ กำกับของใคร",
    options: ["ก. นายกรัฐมนตรี", "ข. ปลัดกระทรวง", "ค. รัฐมนตรีว่าการกระทรวง", "ง. คณะรัฐมนตรี"],
