    id: 727,
    question: "การที่ผู้มอบอำนาจสามารถ \"แก้ไข\" การปฏิบัติราชการของผู้รับมอบอำนาจได้นั้น หมายรวมถึงการสั่งให้ ดำเนินการในแนวทางที่แตกต่างไปจากเดิมได้หรือไม่",
    options: ["ก. ไม่ได้ ทำได้เพียงแนะนำ", "ข. ได้", "ค. ไม่ได้ เพราะเป็นการก้าวก่ายดุลพินิจ", "ง. ได้ แต่ต้องทำเป็นหนังสือ"],
