    question: "หากไม่มีผู้ดำรงตำแหน่งรัฐมนตรีว่าการกระทรวง และรัฐมนตรีช่วยว่าการกระทรวงต้องคำพิพากษาให้ จำคุก คณะรัฐมนตรีจะมอบหมายให้ใครรักษาราชการแทน",
    options: ["ก. ปลัดกระทรวง", "ข. รัฐมนตรีคนใดคนหนึ่ง", "ค. นายกรัฐมนตรี", "ง. อธิบดีผู้มีอาวุโสสูงสุด"],
