    question: "ข้อตกลงตามสัญญาประนีประนอมยอมความที่อำเภอ มีผลผูกพัน \"บุคคลภายนอก\" หรือไม่",
    options: ["ก. ผูกพัน หากเป็นทายาท", "ข. ไม่ผูกพัน มีผลเฉพาะคู่พิพาท", "ค. ผูกพัน หากนายอำเภอรับรอง", "ง. ไม่ผูกพัน เว้นแต่จะระบุไว้ในสัญญา"],
    answer: "ข",
    answerText: "ไม่ผูกพัน มีผลเฉพาะคู่พิพาท",
