    question: "การที่นายกรัฐมนตรีจะแต่งตั้งข้าราชการการเมืองให้ปฏิบัติราชการในสำนักนายกรัฐมนตรีนั้น ไม่รวมถึง ตำแหน่งใด",
    options: ["ก. ที่ปรึกษานายกรัฐมนตรี", "ข. รองเลขาธิการนายกรัฐมนตรีฝ่ายการเมือง", "ค. โฆษกประจำสำนักนายกรัฐมนตรี", "ง. ปลัดสำนักนายกรัฐมนตรี"],
