    question: "หากหัวหน้าส่วนราชการประจำอำเภอไม่อาจปฏิบัติราชการได้ ใครจะเป็นผู้รักษาราชการแทน",
    options: ["ก. นายอำเภอแต่งตั้ง", "ข. ข้าราชการในสังกัดนั้นที่มีอาวุโสสูงสุด", "ค. ปลัดอำเภอ", "ง. กฎหมายไม่ได้กำหนดไว้โดยเฉพาะ"],
