    options: ["ก. ใช่ เป็นการโอนอำนาจเด็ดขาด", "ข. ไม่ใช่ เป็นการปฏิบัติราชการแทน", "ค. ใช่ แต่เฉพาะเรื่องที่ระบุไว้", "ง. ไม่ใช่ เป็นเพียงการกำกับดูแล"],
