    question: "หากไม่มีผู้ดำรงตำแหน่งอธิบดี และรองอธิบดีคนเดียวที่มีอยู่ก็ไม่อาจปฏิบัติราชการได้ ปลัดกระทรวงจะ แต่งตั้งใครรักษาราชการแทน",
    options: ["ก. ข้าราชการในกรมซึ่งดำรงตำแหน่งเทียบเท่ารองอธิบดี หรือตั้งแต่หัวหน้ากองขึ้นไป", "ข. ปลัดกระทรวงต้องรักษาการแทนเอง", "ค. รัฐมนตรีแต่งตั้ง", "ง. รองปลัดกระทรวง"],
