    question: "ผู้ว่าราชการจังหวัดมีอำนาจสั่งให้หัวหน้าส่วนราชการประจำจังหวัดรายงานผลการปฏิบัติงานได้หรือไม่",
    options: ["ก. ได้ ในฐานะผู้บังคับบัญชา", "ข. ไม่ได้ เพราะอยู่คนละสังกัด", "ค. ได้ แต่ต้องผ่านคณะกรมการจังหวัด", "ง. ไม่ได้ เว้นแต่อธิบดีจะอนุญาต"],
