    options: ["ก. การรวมอำนาจไว้ที่ส่วนกลาง", "ข. การกระจายอำนาจให้ท้องถิ่นอย่างสมบูรณ์", "ค. การผสมผสานระหว่างการรวมอำนาจ (ส่วนกลาง-ภูมิภาค) และการกระจายอำนาจ (ส่วนท้องถิ่น)", "ง. การให้ความสำคัญกับราชการส่วนภูมิภาคมากที่สุด"],
