    question: "หากกฎหมายว่าด้วยสภาตำบลและองค์การบริหารส่วนตำบล อ้างถึง \"ประกาศของคณะปฏิวัติ ฉบับที่ 218\" จะมีผลอย่างไร",
    options: ["ก. ไม่มีผล เพราะเป็นกฎหมายคนละระดับกัน", "ข. ให้ถือว่าอ้างถึงพระราชบัญญัติระเบียบบริหารราชการแผ่นดินในบทมาตราที่มีนัยเช่นเดียวกัน", "ค. ต้องรอการแก้ไขกฎหมายว่าด้วยสภาตำบลฯ ก่อนจึงจะมีผล", "ง. ให้อำนาจรัฐมนตรีว่าการกระทรวงมหาดไทยในการตีความ"],
