    question: "ปลัดสำนักนายกรัฐมนตรีมีอำนาจกำหนดแนวทางและแผนการปฏิบัติราชการของหน่วยงานใด",
    options: ["ก. ทุกส่วนราชการในสำนักนายกรัฐมนตรี", "ข. สำนักนายกรัฐมนตรี", "ค. สำนักงานปลัดสำนักนายกรัฐมนตรี", "ง. ส่วนราชการที่มิได้ขึ้นตรงต่อนายกรัฐมนตรี"],
