    question: "การที่หัวหน้าคณะผู้แทนอาจมอบอำนาจให้บุคคลในคณะผู้แทนปฏิบัติราชการแทนได้นั้น เป็นไปเพื่อ วัตถุประสงค์ใด",
    options: ["ก. เพื่อความคล่องตัวในการปฏิบัติราชการในต่างประเทศ", "ข. เพื่อลดภาระของหัวหน้าคณะผู้แทน", "ค. เพื่อฝึกฝนผู้ใต้บังคับบัญชา", "ง. ถูกทุกข้อ"],
    answer: "ง",
