    question: "อำนาจหน้าที่ของ \"สำนักงานคณะกรรมการพัฒนาระบบราชการ\" คืออะไร",
    options: ["ก. กำหนดนโยบายพัฒนาระบบราชการ", "ข. รับผิดชอบงานธุรการของ ก.พ.ร.", "ค. ประเมินผลการปฏิบัติราชการของส่วนราชการ", "ง. แต่งตั้งโยกย้ายข้าราชการระดับสูง"],
    answer: "ข",
    answerText: "รับผิดชอบงานธุรการของ ก.พ.ร.",
