    question: "หากกระทรวงหนึ่งต้องการจัดตั้ง \"กรม\" ใหม่ จะต้องดำเนินการอย่างไร",
    options: ["ก. ออกเป็นกฎกระทรวง", "ข. ตราเป็นพระราชกฤษฎีกา", "ค. ตราเป็นพระราชบัญญัติ", "ง. เสนอขออนุมัติจาก ก.พ.ร."],
