    question: "การที่ปลัดกระทรวงรักษาราชการแทนรัฐมนตรีว่าการกระทรวง สามารถทำได้หรือไม่",
    options: ["ก. ได้ หาก ครม. มอบหมาย", "ข. ไม่ได้โดยเด็ดขาด", "ค. ได้เฉพาะกรณีฉุกเฉิน", "ง. ได้หากนายกรัฐมนตรีสั่งการ"],
